-- Staging only: actual quarantined SQL with synthetic profiles and Auth claims/sessions.
-- This fixture seeds explicit artificial catalog/configuration values, never clinical defaults.
-- No HTTP sign-in, browser/layout, parallel-transaction, actual qualification or clinical-approval claim.
-- No grants or DDL. Both the inner synthetic scope and the outer transaction roll back.
BEGIN;
DO $test$
<<fixture>>
DECLARE
 t uuid:=gen_random_uuid();u uuid:=gen_random_uuid();s uuid:=gen_random_uuid();r uuid:=gen_random_uuid();
 reviewer uuid:=gen_random_uuid();review_session uuid:=gen_random_uuid();review_role uuid:=gen_random_uuid();
 c uuid:=gen_random_uuid();other_client uuid:=gen_random_uuid();setting_id uuid:=gen_random_uuid();device_id uuid:=gen_random_uuid();calibration_id uuid:=gen_random_uuid();
 employee_id uuid:=gen_random_uuid();qualification_id uuid:=gen_random_uuid();qualification_doc uuid:=gen_random_uuid();review_scope uuid:=gen_random_uuid();
 measurement uuid;second_measurement uuid;follow_id uuid;invalidation_id uuid;
 measurement_request uuid:=gen_random_uuid();second_request uuid:=gen_random_uuid();follow_request uuid:=gen_random_uuid();invalidation_request uuid:=gen_random_uuid();
 path_request uuid:=gen_random_uuid();revision_request uuid:=gen_random_uuid();correction_request uuid:=gen_random_uuid();review_request uuid:=gen_random_uuid();decision_request uuid:=gen_random_uuid();
 claims jsonb;review_claims jsonb;native_packet jsonb;second_native_packet jsonb;follow_packet jsonb;invalidation_packet jsonb;
 native_original jsonb;native_receipt jsonb;follow_original jsonb;invalidation_original jsonb;legacy_original jsonb;return_request_packet jsonb;return_request_receipt jsonb;catalog_original jsonb;configuration_original jsonb;source_original jsonb;
 entry jsonb;path_packet jsonb;path_receipt jsonb;path_original jsonb;revision_packet jsonb;revision_receipt jsonb;correction_packet jsonb;correction_receipt jsonb;
 review_packet jsonb;review_receipt jsonb;decision_packet jsonb;decision_receipt jsonb;return_packet jsonb;return_receipt jsonb;
 value jsonb;bad jsonb;page1 jsonb;page2 jsonb;query_packet jsonb;
 observed timestamptz:=date_trunc('milliseconds',clock_timestamp()-interval '2 hours');controlled timestamptz:=date_trunc('milliseconds',clock_timestamp()-interval '1 hour');
 today date:=(clock_timestamp() at time zone 'Europe/Berlin')::date;observed_text text;controlled_text text;passed boolean:=false;fixture_count integer:=0;
BEGIN
 BEGIN
  INSERT INTO public.tenants(id,name) VALUES(t,'CP365 Vital synthetic rollback fixture');
  INSERT INTO public.roles(id,key,name) VALUES(r,'cp365_vital_'||r,'Synthetic own Vital role'),(review_role,'cp365_vital_review_'||review_role,'Synthetic independent Vital role');
  INSERT INTO public.role_permissions(role_id,permission_key) SELECT own.role_id,permission.permission_key FROM unnest(ARRAY[r,review_role]) AS own(role_id) CROSS JOIN unnest(ARRAY['pflege.vitals.view','pflege.vitals.manage','pflege.documentation.sign']) AS permission(permission_key);
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES(u,u||'@example.invalid','{}','{}'),(reviewer,reviewer||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=t,role_id=r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic measuring author' WHERE id=u;
  UPDATE public.profiles SET tenant_id=t,role_id=review_role,role_key='pfleger',is_active=true,status='active',display_name='Synthetic independent reviewer' WHERE id=reviewer;
  INSERT INTO auth.sessions(id,user_id,not_after) VALUES(s,u,clock_timestamp()+interval '1 hour'),(review_session,reviewer,clock_timestamp()+interval '1 hour');
  INSERT INTO public.clients(id,tenant_id,first_name,last_name,status,lifecycle_status) VALUES(c,t,'Synthetic','Vital case','aktiv','aktiv'),(other_client,t,'Synthetic','Other case','aktiv','aktiv');
  INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active) VALUES(t,c,'pflege','active',true),(t,other_client,'pflege','active',true);
  claims:=jsonb_build_object('sub',u,'role','authenticated','session_id',s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  review_claims:=jsonb_build_object('sub',reviewer,'role','authenticated','session_id',review_session,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  PERFORM set_config('request.jwt.claims',claims::text,true);
  observed_text:=to_char(observed at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');controlled_text:=to_char(controlled at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  -- A clean quarantined package has no catalog seed. Do not overwrite any existing catalog.
  IF EXISTS(SELECT 1 FROM public.vital_sign_catalog WHERE key='pulse') THEN RAISE EXCEPTION 'Vital fixture requires an isolated empty synthetic pulse catalog slot';END IF;
  INSERT INTO public.vital_sign_catalog(key,category,label,short_label,default_unit,components,default_enabled,is_active,sort_order) VALUES('pulse','basis','Synthetic fixture pulse','Synthetic','/min','["value"]',true,true,9999);
  INSERT INTO public.client_vital_sign_settings(id,tenant_id,client_id,vital_key,enabled,limits,schedule,created_by,updated_by,source_kind,approved_by,valid_from,valid_to,active,revision)
  VALUES(setting_id,t,c,'pulse',true,'{"value":{"min":1,"max":9}}','{}',u,u,'individual_configuration',u,observed-interval '1 day',null,true,1);
  SELECT to_jsonb(v) INTO catalog_original FROM public.vital_sign_catalog v WHERE v.key='pulse';
  SELECT to_jsonb(v) INTO configuration_original FROM public.client_vital_sign_settings v WHERE v.id=setting_id;
  native_packet:=jsonb_build_object('clientId',c,'type','pulse','occurredAt',observed_text,'valuesJson','{"value":15}','contextJson','{"fixture":"explicit synthetic observation"}','note','Synthetic actual observation; no clinical interpretation','catalogVersion',catalog_original->'updated_at','configurationVersion',configuration_original->'updated_at');
  measurement:=care_private.record_vital_measurement(measurement_request,native_packet);
  SELECT to_jsonb(v) INTO native_original FROM public.vital_sign_measurements v WHERE v.id=measurement;
  IF native_original->'values' IS DISTINCT FROM '{"value":15}'::jsonb OR (native_original->>'occurred_at')::timestamptz IS DISTINCT FROM observed OR native_original->>'recorded_by' IS DISTINCT FROM u::text OR native_original->'creation_payload' IS DISTINCT FROM native_packet OR native_original->>'flag_status' IS DISTINCT FROM 'outside_configured_range' THEN RAISE EXCEPTION 'Native observation or own explicit configuration was inferred/replaced';END IF;
  native_receipt:=public.confirm_ambulatory_vital_measurement(measurement,measurement_request,native_packet);
  IF native_receipt IS DISTINCT FROM native_original THEN RAISE EXCEPTION 'Own native measurement full confirmation differs';END IF;
  IF care_private.record_vital_measurement(measurement_request,native_packet) IS DISTINCT FROM measurement THEN RAISE EXCEPTION 'Native exact replay duplicated measurement';END IF;
  BEGIN UPDATE public.vital_sign_measurements SET display_value='Changed native original' WHERE id=measurement;RAISE EXCEPTION 'Captured native measurement mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.vital_sign_measurements WHERE id=measurement;RAISE EXCEPTION 'Captured native measurement deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.confirm_ambulatory_vital_measurement(measurement,measurement_request,jsonb_set(native_packet,'{note}','"Changed own packet"'));RAISE EXCEPTION 'Changed native packet confirmed as own';EXCEPTION WHEN SQLSTATE 'P0V01' THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(measurement_request,jsonb_set(native_packet,'{valuesJson}','"{\"value\":16}"'));RAISE EXCEPTION 'Changed native replay accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(gen_random_uuid(),native_packet||'{"unexpected":"hidden write"}');RAISE EXCEPTION 'Unknown native payload field accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(gen_random_uuid(),jsonb_set(native_packet,'{catalogVersion}',to_jsonb(observed_text)));RAISE EXCEPTION 'Stale catalog version accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(gen_random_uuid(),jsonb_set(native_packet,'{configurationVersion}',to_jsonb(observed_text)));RAISE EXCEPTION 'Stale explicit configuration accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(gen_random_uuid(),jsonb_set(native_packet,'{valuesJson}','"{\"unknown\":15}"'));RAISE EXCEPTION 'Unknown native component accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_measurement(gen_random_uuid(),jsonb_set(native_packet,'{occurredAt}',to_jsonb(to_char(clock_timestamp()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))));RAISE EXCEPTION 'Future actual measurement accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.client_vital_sign_settings SET enabled=false WHERE id=setting_id;PERFORM care_private.record_vital_measurement(gen_random_uuid(),native_packet);RAISE EXCEPTION 'Disabled own measurement type accepted';EXCEPTION WHEN check_violation OR serialization_failure THEN NULL;END;
  IF (SELECT count(*) FROM public.vital_sign_events WHERE measurement_id=measurement) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Synthetic out-of-range source event not retained exactly once';END IF;

  follow_packet:=jsonb_build_object('measurementId',measurement,'observedAt',controlled_text,'observation','Synthetic follow-up explicitly observed','action','Synthetic action explicitly recorded','responsiblePerson','Synthetic author','outcome','resolved','nextReviewAt','');
  follow_id:=care_private.record_vital_follow_up(follow_request,follow_packet);
  SELECT to_jsonb(f) INTO value FROM public.vital_measurement_follow_ups f WHERE f.id=follow_id;follow_original:=public.confirm_ambulatory_vital_follow_up(follow_id,follow_request,follow_packet);IF follow_original IS DISTINCT FROM value THEN RAISE EXCEPTION 'Own full follow-up confirmation differs';END IF;
  IF care_private.record_vital_follow_up(follow_request,follow_packet) IS DISTINCT FROM follow_id THEN RAISE EXCEPTION 'Follow-up exact replay duplicated original';END IF;
  BEGIN UPDATE public.vital_measurement_follow_ups SET observation='Changed actual follow-up original' WHERE id=follow_id;RAISE EXCEPTION 'Actual follow-up mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_follow_up(follow_request,jsonb_set(follow_packet,'{observation}','"Changed follow-up"'));RAISE EXCEPTION 'Changed follow-up replay accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_follow_up(gen_random_uuid(),jsonb_set(follow_packet,'{observedAt}',to_jsonb(to_char(observed-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));RAISE EXCEPTION 'Follow-up predating actual measurement accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.record_vital_follow_up(gen_random_uuid(),follow_packet||'{"outcome":"ongoing"}');RAISE EXCEPTION 'Ongoing follow-up without explicit next time accepted';EXCEPTION WHEN check_violation THEN NULL;END;

  INSERT INTO public.vital_measurement_devices(id,tenant_id,client_id,name,serial_number,method,active,revision,recorded_by) VALUES(device_id,t,c,'Synthetic device original','SYNTHETIC-ONLY','Synthetic documented method',true,1,u);
  INSERT INTO public.vital_device_calibrations(id,tenant_id,device_id,status,performed_at,valid_until,limitation,revision,recorded_by) VALUES(calibration_id,t,device_id,'valid',observed-interval '2 days',clock_timestamp()+interval '1 day','Synthetic fixture evidence',1,u);
  source_original:=care_private.read_vital_care_path_context(t,c,measurement,u);
  IF jsonb_array_length(source_original->'measurements') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'settings') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'devices') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'calibrations') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'followUps') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'events') IS DISTINCT FROM 1 OR jsonb_array_length(source_original->'invalidations') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'Full current source context truncated or inferred';END IF;
  entry:=jsonb_build_object('kind','measurement_review','tenantId',t,'clientId',c,'measurementId',measurement,'observedAt',source_original#>'{measurements,0,payload,occurred_at}','title','Synthetic explicit original review',
   'interpretation',jsonb_build_object('state','outside_configured_range','summary','Synthetic value and explicit fixture limit were compared; no diagnostic conclusion','measurementType','pulse','values',native_original->'values','unit','/min','context',native_original->'context','configuredLimitId',setting_id),
   'device',jsonb_build_object('deviceId',device_id,'calibrationId',calibration_id,'suitability','confirmed','method','Synthetic documented method','limitation',''),
   'response',jsonb_build_object('state','pending','occurredAt',null,'action','','reason','','contactName','','responsibleBy',null),
   'control',jsonb_build_object('state','none','dueAt',null,'performedAt',null,'result','','responsibleBy',null),
   'correction',jsonb_build_object('targetId',null,'reason','','replacementId',null,'approvedBy',null,'approvedAt',null));
  path_packet:=jsonb_build_object('schemaVersion','1','action','create','requestId',path_request,'tenantId',t,'clientId',c,'measurementId',measurement,'actorId',u,'expectedHeadId',null,'expectedRevision',0,'entry',entry,'reason','','original',null,'sources',source_original);
  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{entry,interpretation,values,value}','16'));RAISE EXCEPTION 'Path replaced native measurement value';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{entry,observedAt}',to_jsonb(to_char(observed-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));RAISE EXCEPTION 'Path replaced microsecond actual time';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{entry,response,action}','"Invented performed action"'));RAISE EXCEPTION 'Pending reaction invented actual action';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.vital_device_calibrations SET status='expired' WHERE id=calibration_id;PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{sources}',care_private.read_vital_care_path_context(t,c,measurement,u)));RAISE EXCEPTION 'Expired calibration accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.client_vital_sign_settings SET approved_by=null WHERE id=setting_id;PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{sources}',care_private.read_vital_care_path_context(t,c,measurement,u)));RAISE EXCEPTION 'Unapproved current limit accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.vital_sign_events SET summary='Changed full event source' WHERE measurement_id=measurement;RAISE EXCEPTION 'Retained source event original mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{sources,events,0,payload,summary}','"Changed complete event original"'));RAISE EXCEPTION 'Changed complete source snapshot accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN UPDATE public.vital_measurement_devices SET name='Changed same-scope device original' WHERE id=device_id;PERFORM care_private.commit_vital_care_path_packet(path_packet);RAISE EXCEPTION 'Changed whole device source accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN
   UPDATE public.profiles SET phone='+490000000001' WHERE id=u;
   SELECT ref INTO value FROM jsonb_array_elements(care_private.read_vital_care_path_context(t,c,measurement,u)->'people') AS ref WHERE ref->>'id'=u::text;
   SELECT ref INTO bad FROM jsonb_array_elements(source_original->'people') AS ref WHERE ref->>'id'=u::text;
   IF value->'payload' IS DISTINCT FROM bad->'payload' OR value->'recordedAt' IS DISTINCT FROM bad->'recordedAt' THEN RAISE EXCEPTION 'Synthetic phone change did not isolate the unselected native source facts';END IF;
   IF value->'fingerprint' IS NOT DISTINCT FROM bad->'fingerprint' THEN RAISE EXCEPTION 'Unselected native responsible-person fact missing from full source fingerprint';END IF;
   PERFORM care_private.commit_vital_care_path_packet(path_packet);RAISE EXCEPTION 'Changed full native person source accepted';
  EXCEPTION WHEN serialization_failure THEN NULL;END;

  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{entry,interpretation,state}','"within_configured_range"'));RAISE EXCEPTION 'Chosen normal label contradicted original numeric limits';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.vital_device_calibrations SET performed_at=observed+interval '1 microsecond' WHERE id=calibration_id;PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{sources}',care_private.read_vital_care_path_context(t,c,measurement,u)));RAISE EXCEPTION 'Calibration after actual measurement accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  path_receipt:=care_private.commit_vital_care_path_packet(path_packet);path_original:=path_receipt->'original';
  IF path_receipt->'packet' IS DISTINCT FROM path_packet OR path_original->>'revision' IS DISTINCT FROM '1' OR jsonb_array_length(path_original->'history') IS DISTINCT FROM 1 OR path_original->'payload' IS DISTINCT FROM entry THEN RAISE EXCEPTION 'Initial path lost its exact original packet';END IF;
  IF care_private.commit_vital_care_path_packet(path_packet) IS DISTINCT FROM path_receipt OR care_private.confirm_vital_care_path_packet(t,c,measurement,u,path_request,path_packet) IS DISTINCT FROM path_receipt THEN RAISE EXCEPTION 'Path exact own confirmation/replay mismatch';END IF;
  BEGIN PERFORM care_private.commit_vital_care_path_packet(jsonb_set(path_packet,'{entry,title}','"Changed request content"'));RAISE EXCEPTION 'Changed path replay accepted';EXCEPTION WHEN check_violation OR serialization_failure THEN NULL;END;
  BEGIN UPDATE public.vital_care_paths SET reason='Mutated original' WHERE id=(path_original->>'id')::uuid;RAISE EXCEPTION 'Path original mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM care_private.vital_care_path_receipts WHERE tenant_id=t AND request_id=path_request;RAISE EXCEPTION 'Path receipt deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;

  entry:=entry||jsonb_build_object('kind','case_resolution','title','Synthetic expressly resolved care path','response',jsonb_build_object('state','performed','occurredAt',controlled_text,'action','Synthetic actual response recorded','reason','Synthetic configured range prompted explicit review','contactName','Synthetic responsible service','responsibleBy',u),'control',jsonb_build_object('state','resolved','dueAt',controlled_text,'performedAt',controlled_text,'result','Synthetic control explicitly completed; no clinical approval asserted','responsibleBy',u));
  revision_packet:=path_packet||jsonb_build_object('action','revise','requestId',revision_request,'expectedHeadId',path_original->'headId','expectedRevision',1,'entry',entry,'reason','Explicit synthetic append-only continuation','original',path_original,'sources',care_private.read_vital_care_path_context(t,c,measurement,u));
  revision_receipt:=care_private.commit_vital_care_path_packet(revision_packet);
  IF revision_receipt#>>'{original,rootId}' IS DISTINCT FROM path_original->>'rootId' OR revision_receipt#>>'{original,revision}' IS DISTINCT FROM '2' OR jsonb_array_length(revision_receipt#>'{original,history}') IS DISTINCT FROM 2 OR revision_receipt#>'{original,history,0,payload}' IS DISTINCT FROM path_packet->'entry' THEN RAISE EXCEPTION 'Append-only revision lost initial native/history binding';END IF;
  IF care_private.confirm_vital_care_path_packet(t,c,measurement,u,path_request,path_packet) IS DISTINCT FROM path_receipt THEN RAISE EXCEPTION 'Historical exact path receipt changed after revision';END IF;
  BEGIN PERFORM care_private.commit_vital_care_path_packet(revision_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',jsonb_set(entry,'{title}','"Lost CAS update"'),'sources',care_private.read_vital_care_path_context(t,c,measurement,u)));RAISE EXCEPTION 'Stale path head accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  page1:=care_private.read_vital_care_path_page(t,c,measurement,u,null,null,1);
  IF jsonb_array_length(page1->'rows') IS DISTINCT FROM 1 OR page1#>>'{rows,0,headId}' IS DISTINCT FROM revision_receipt#>>'{original,headId}' THEN RAISE EXCEPTION 'Path history did not expose latest head';END IF;
  page2:=care_private.read_vital_care_path_page(t,c,measurement,u,(page1->>'nextCursorRecordedAt')::timestamptz,(page1->>'nextCursorId')::uuid,1);
  IF jsonb_array_length(page2->'rows') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'Path cursor duplicated original root';END IF;

  -- The following qualification is explicit synthetic fixture evidence, not a real credential.
  INSERT INTO public.employees(id,tenant_id,profile_id,first_name,last_name,status,start_date) VALUES(employee_id,t,reviewer,'Synthetic','Reviewer','aktiv',today-30);
  INSERT INTO public.employee_employment_details(tenant_id,employee_id,employment_status) VALUES(t,employee_id,'active');
  INSERT INTO public.employee_documents(id,tenant_id,employee_id,category,title,file_name,storage_path,valid_until) VALUES(qualification_doc,t,employee_id,'qualification','Synthetic qualification document','synthetic.pdf','synthetic-only/'||qualification_doc||'.pdf',today+30);
  INSERT INTO public.employee_qualifications(id,tenant_id,employee_id,qualification_type,title,issued_at,valid_until,document_id,verified_by,verified_at,status) VALUES(qualification_id,t,employee_id,'synthetic_vital_review','Synthetic Vital scope qualification',today-30,today+30,qualification_doc,'Synthetic fixture provisioner',observed-interval '1 day','valid');
  INSERT INTO care_private.vital_care_review_scopes(id,tenant_id,employee_id,qualification_id,kind,qualification_fingerprint,document_fingerprint,approved_by,approved_at,valid_until)
  SELECT review_scope,t,fixture.employee_id,fixture.qualification_id,'vital_care_review','sha256:'||encode(extensions.digest(convert_to(to_jsonb(q)::text,'UTF8'),'sha256'),'hex'),'sha256:'||encode(extensions.digest(convert_to(to_jsonb(d)::text,'UTF8'),'sha256'),'hex'),u,observed-interval '1 hour',clock_timestamp()+interval '1 day' FROM public.employee_qualifications q JOIN public.employee_documents d ON d.id=q.document_id WHERE q.id=qualification_id;
  review_packet:=jsonb_build_object('schemaVersion','1','action','request','requestId',review_request,'tenantId',t,'clientId',c,'measurementId',measurement,'actorId',u,'expectedHeadId',null,'expectedRevision',0,'careOriginal',revision_receipt->'original','sources',care_private.read_vital_care_path_context(t,c,measurement,u),'reviewOriginal',null,'reason','Synthetic independent review of explicit completed path','requiredChange','','rationale','');
  review_receipt:=care_private.commit_vital_care_review(review_packet);
  IF review_receipt#>>'{original,history,0,id}' IS DISTINCT FROM review_receipt#>>'{original,rootId}' THEN RAISE EXCEPTION 'First review event and immutable root identity diverge from Web domain contract';END IF;
  IF review_receipt#>>'{original,status}' IS DISTINCT FROM 'requested' OR jsonb_array_length(review_receipt#>'{original,history}') IS DISTINCT FROM 1 OR review_receipt#>'{original,history,0,qualification}' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Review request invented independent acceptance/qualification';END IF;
  IF care_private.commit_vital_care_review(review_packet) IS DISTINCT FROM review_receipt OR care_private.confirm_vital_care_review(t,c,measurement,u,review_request,review_packet) IS DISTINCT FROM review_receipt THEN RAISE EXCEPTION 'Review exact own confirmation/replay mismatch';END IF;
  decision_packet:=review_packet||jsonb_build_object('action','accept','requestId',decision_request,'expectedHeadId',review_receipt#>'{original,headId}','expectedRevision',1,'reviewOriginal',review_receipt->'original','reason','','rationale','Synthetic independent source and complete path review recorded');
  BEGIN PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Measuring/requesting author accepted own review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  PERFORM set_config('request.jwt.claims',review_claims::text,true);decision_packet:=decision_packet||jsonb_build_object('actorId',reviewer,'sources',care_private.read_vital_care_path_context(t,c,measurement,reviewer));
  BEGIN DELETE FROM public.role_permissions WHERE role_id=review_role AND permission_key='pflege.documentation.sign';PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Own missing sign permission accepted review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.employee_employment_details AS employment SET employment_status='suspended' WHERE employment.employee_id=fixture.employee_id;PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Suspended reviewer accepted clinical review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.employee_qualifications SET status='expired' WHERE id=qualification_id;PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Expired qualification accepted review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.employee_documents SET storage_path='' WHERE id=qualification_doc;PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Missing qualification document accepted review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE care_private.vital_care_review_scopes SET revoked_at=clock_timestamp() WHERE id=review_scope;PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Revoked Vital scope accepted review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE auth.sessions SET not_after=clock_timestamp()-interval '1 minute' WHERE id=review_session;PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Expired actual reviewer session accepted review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.commit_vital_care_review(jsonb_set(decision_packet,'{careOriginal,payload,title}','"Replaced original path"'));RAISE EXCEPTION 'Replaced complete path original accepted review';EXCEPTION WHEN serialization_failure THEN NULL;END;
  decision_receipt:=care_private.commit_vital_care_review(decision_packet);
  IF decision_receipt#>>'{original,status}' IS DISTINCT FROM 'accepted' OR decision_receipt#>>'{original,history,1,actorId}' IS DISTINCT FROM reviewer::text OR decision_receipt#>>'{original,history,1,qualification,profileId}' IS DISTINCT FROM reviewer::text OR jsonb_array_length(decision_receipt#>'{original,history}') IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'Independent synthetic review did not retain qualified actor and original request';END IF;
  IF care_private.commit_vital_care_review(decision_packet) IS DISTINCT FROM decision_receipt OR care_private.confirm_vital_care_review(t,c,measurement,reviewer,decision_request,decision_packet) IS DISTINCT FROM decision_receipt THEN RAISE EXCEPTION 'Independent decision exact replay/own receipt changed';END IF;
  BEGIN PERFORM care_private.commit_vital_care_review(decision_packet||jsonb_build_object('requestId',gen_random_uuid()));RAISE EXCEPTION 'Second decision on same review accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN UPDATE public.vital_care_review_events SET rationale='Changed immutable decision' WHERE request_id=decision_request;RAISE EXCEPTION 'Review decision mutable';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN DELETE FROM public.vital_care_review_receipts WHERE request_id=decision_request;RAISE EXCEPTION 'Review own receipt deletable';EXCEPTION WHEN check_violation THEN NULL;END;
  page1:=care_private.read_vital_care_review_page(t,c,measurement,reviewer,null,null,1);IF page1#>>'{rows,0,status}' IS DISTINCT FROM 'accepted' OR jsonb_array_length(page1#>'{rows,0,history}') IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'Review page lost immutable history';END IF;

  -- A subsequent explicit correction retains the accepted earlier review and obtains its own review root.
  PERFORM set_config('request.jwt.claims',claims::text,true);
  entry:=entry||jsonb_build_object('kind','correction','title','Synthetic append-only correction of original wording','correction',jsonb_build_object('targetId',path_original->'headId','reason','Explicit synthetic correction retaining the first original','replacementId',correction_request,'approvedBy',u,'approvedAt',controlled_text));
  correction_packet:=revision_packet||jsonb_build_object('requestId',correction_request,'expectedHeadId',revision_receipt#>'{original,headId}','expectedRevision',2,'entry',entry,'reason','Append-only synthetic correction preserves every earlier fact','original',revision_receipt->'original','sources',care_private.read_vital_care_path_context(t,c,measurement,u));
  correction_receipt:=care_private.commit_vital_care_path_packet(correction_packet);
  IF correction_receipt#>>'{original,revision}' IS DISTINCT FROM '3' OR jsonb_array_length(correction_receipt#>'{original,history}') IS DISTINCT FROM 3 OR correction_receipt#>'{original,history,0,payload}' IS DISTINCT FROM path_packet->'entry' OR correction_receipt#>'{original,history,1,payload}' IS DISTINCT FROM revision_packet->'entry' THEN RAISE EXCEPTION 'Correction rewrote original path history';END IF;
  IF care_private.commit_vital_care_path_packet(correction_packet) IS DISTINCT FROM correction_receipt THEN RAISE EXCEPTION 'Correction exact replay differs';END IF;
  return_packet:=review_packet||jsonb_build_object('requestId',gen_random_uuid(),'careOriginal',correction_receipt->'original','sources',care_private.read_vital_care_path_context(t,c,measurement,u));
  return_receipt:=care_private.commit_vital_care_review(return_packet);return_request_packet:=return_packet;return_request_receipt:=return_receipt;
  IF return_receipt#>>'{original,history,0,id}' IS DISTINCT FROM return_receipt#>>'{original,rootId}' THEN RAISE EXCEPTION 'Correction review first event and root identity diverge';END IF;
  PERFORM set_config('request.jwt.claims',review_claims::text,true);
  return_packet:=return_packet||jsonb_build_object('action','return','requestId',gen_random_uuid(),'actorId',reviewer,'expectedHeadId',return_receipt#>'{original,headId}','expectedRevision',1,'reviewOriginal',return_receipt->'original','sources',care_private.read_vital_care_path_context(t,c,measurement,reviewer),'reason','Synthetic return with explicit unmet evidence','requiredChange','Record a concrete independently traceable synthetic correction','rationale','');
  return_receipt:=care_private.commit_vital_care_review(return_packet);
  IF return_receipt#>>'{original,status}' IS DISTINCT FROM 'returned' OR return_receipt#>>'{original,history,1,requiredChange}' IS DISTINCT FROM return_packet->>'requiredChange' OR return_receipt#>>'{original,history,1,rationale}' IS DISTINCT FROM '' THEN RAISE EXCEPTION 'Return invented acceptance or lost required correction';END IF;
  IF care_private.commit_vital_care_review(return_packet) IS DISTINCT FROM return_receipt OR care_private.confirm_vital_care_review(t,c,measurement,reviewer,(return_packet->>'requestId')::uuid,return_packet) IS DISTINCT FROM return_receipt THEN RAISE EXCEPTION 'Return exact own replay/confirmation differs';END IF;
  page1:=care_private.read_vital_care_review_page(t,c,measurement,reviewer,null,null,1);
  page2:=care_private.read_vital_care_review_page(t,c,measurement,reviewer,(page1->>'nextCursorRecordedAt')::timestamptz,(page1->>'nextCursorId')::uuid,1);
  IF jsonb_array_length(page1->'rows') IS DISTINCT FROM 1 OR jsonb_array_length(page2->'rows') IS DISTINCT FROM 1 OR page1#>>'{rows,0,rootId}' IS NOT DISTINCT FROM page2#>>'{rows,0,rootId}' OR page1#>>'{rows,0,status}' IS DISTINCT FROM 'returned' OR page2#>>'{rows,0,status}' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'Review cursor duplicated/lost independent historical decision';END IF;
  BEGIN PERFORM care_private.read_vital_care_path_page(t,c,measurement,reviewer,clock_timestamp(),null,1);RAISE EXCEPTION 'Partial path cursor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.read_vital_care_review_page(t,c,measurement,reviewer,null,null,0);RAISE EXCEPTION 'Invalid review page size accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN value:=public.confirm_ambulatory_vital_measurement(measurement,measurement_request,native_packet);IF value IS NOT NULL THEN RAISE EXCEPTION 'Different reviewer confirmed native author write as own';END IF;EXCEPTION WHEN insufficient_privilege OR SQLSTATE 'P0V01' THEN NULL;END;
  PERFORM set_config('request.jwt.claims',claims::text,true);
  invalidation_packet:=jsonb_build_object('measurementId',measurement,'reason','Synthetic original explicitly marked invalid; alerts and reactions remain evidence');
  invalidation_id:=care_private.invalidate_vital_measurement(invalidation_request,invalidation_packet);
  SELECT to_jsonb(i) INTO value FROM public.vital_measurement_invalidations i WHERE i.id=invalidation_id;invalidation_original:=public.confirm_ambulatory_vital_invalidation(invalidation_id,invalidation_request,invalidation_packet);IF invalidation_original IS DISTINCT FROM value THEN RAISE EXCEPTION 'Own full invalidation confirmation differs';END IF;
  IF care_private.invalidate_vital_measurement(invalidation_request,invalidation_packet) IS DISTINCT FROM invalidation_id THEN RAISE EXCEPTION 'Invalidation exact replay duplicated original';END IF;
  BEGIN UPDATE public.vital_measurement_invalidations SET reason='Changed original invalidation' WHERE id=invalidation_id;RAISE EXCEPTION 'Invalidation original mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.invalidate_vital_measurement(invalidation_request,jsonb_set(invalidation_packet,'{reason}','"Changed original correction reason"'));RAISE EXCEPTION 'Changed invalidation replay accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.invalidate_vital_measurement(gen_random_uuid(),invalidation_packet);RAISE EXCEPTION 'Second invalidation accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  IF (SELECT to_jsonb(v) FROM public.vital_sign_measurements v WHERE v.id=measurement) IS DISTINCT FROM native_original OR (SELECT count(*) FROM public.vital_sign_events WHERE measurement_id=measurement) IS DISTINCT FROM 1 OR (SELECT count(*) FROM public.vital_measurement_follow_ups WHERE measurement_id=measurement) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Path/review/invalidation rewrote native observation, actual follow-up or event evidence';END IF;
  value:=care_private.read_vital_care_path_context(t,c,measurement,u);IF jsonb_array_length(value->'invalidations') IS DISTINCT FROM 1 OR jsonb_array_length(value->'events') IS DISTINCT FROM 1 OR jsonb_array_length(value->'followUps') IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Invalidation hid original evidence';END IF;

  IF public.confirm_ambulatory_vital_measurement(measurement,measurement_request,native_packet) IS DISTINCT FROM native_original OR care_private.confirm_vital_care_path_packet(t,c,measurement,u,path_request,path_packet) IS DISTINCT FROM path_receipt THEN RAISE EXCEPTION 'Historical own native/path receipt lost after invalidation';END IF;
  BEGIN PERFORM care_private.record_vital_follow_up(gen_random_uuid(),follow_packet);RAISE EXCEPTION 'New actual follow-up on invalidated measurement accepted';EXCEPTION WHEN check_violation OR serialization_failure THEN NULL;END;

  -- A historical capture timestamp is never converted into a fabricated actual observation.
  second_measurement:=gen_random_uuid();
  INSERT INTO public.vital_sign_measurements(id,tenant_id,client_id,vital_key,values,display_value,unit,context,note,source,flag_status,recorded_by,recorded_by_name,measured_at,occurred_at) VALUES(second_measurement,t,c,'pulse','{"value":4}','4','/min','{}','Synthetic imported capture without actual time','import','unrated',u,'Synthetic legacy author',observed,null);
  BEGIN PERFORM care_private.record_vital_follow_up(gen_random_uuid(),jsonb_set(follow_packet,'{measurementId}',to_jsonb(second_measurement)));RAISE EXCEPTION 'Historical capture time became actual follow-up source';EXCEPTION WHEN check_violation THEN NULL;END;
  value:=jsonb_build_object('measurementId',second_measurement,'reason','Synthetic legacy capture corrected without inventing actual time');
  PERFORM care_private.invalidate_vital_measurement(gen_random_uuid(),value);
  SELECT to_jsonb(v) INTO legacy_original FROM public.vital_sign_measurements v WHERE v.id=second_measurement;
  IF (SELECT occurred_at FROM public.vital_sign_measurements WHERE id=second_measurement) IS NOT NULL OR (SELECT measured_at FROM public.vital_sign_measurements WHERE id=second_measurement) IS DISTINCT FROM observed THEN RAISE EXCEPTION 'Legacy correction invented or replaced actual/capture time';END IF;

  -- Every own-role, actual session, active-client and identity gate is checked on real SQL.
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.vitals.view';PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Other reviewer role lent its view permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.vitals.manage';PERFORM care_private.record_vital_measurement(gen_random_uuid(),native_packet);RAISE EXCEPTION 'Other reviewer role lent its manage permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.vitals.manage';PERFORM care_private.record_vital_measurement(measurement_request,native_packet);RAISE EXCEPTION 'Exact native replay bypassed current manage permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM set_config('request.jwt.claims',review_claims::text,true);DELETE FROM public.role_permissions WHERE role_id=review_role AND permission_key='pflege.documentation.sign';PERFORM care_private.commit_vital_care_review(decision_packet);RAISE EXCEPTION 'Exact decision replay bypassed current sign permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE auth.sessions SET not_after=clock_timestamp()-interval '1 minute' WHERE id=s;PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Expired own session read confidential source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM set_config('request.jwt.claims',(claims||jsonb_build_object('exp',extract(epoch from clock_timestamp()-interval '1 minute')::bigint))::text,true);PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Expired token read confidential source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.profiles SET is_active=false WHERE id=u;PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Inactive own profile read source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.clients SET lifecycle_status='archiviert' WHERE id=c;PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Inactive care lifecycle read source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.client_module_assignments SET is_active=false WHERE tenant_id=t AND client_id=c AND module_key='pflege';PERFORM care_private.read_vital_care_path_context(t,c,measurement,u);RAISE EXCEPTION 'Missing active Pflege assignment read source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.read_vital_care_path_context(t,other_client,measurement,u);RAISE EXCEPTION 'Other client read measurement source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.read_vital_care_path_context(gen_random_uuid(),c,measurement,u);RAISE EXCEPTION 'Foreign tenant parameter read source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.read_vital_care_path_context(t,c,measurement,reviewer);RAISE EXCEPTION 'Foreign actor parameter read source';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM care_private.confirm_vital_care_review(t,c,measurement,u,decision_request,decision_packet);RAISE EXCEPTION 'Author read independent reviewer receipt as own';EXCEPTION WHEN SQLSTATE 'P0H03' THEN NULL;END;
  IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('record_ambulatory_vital_measurement','record_ambulatory_vital_follow_up','invalidate_ambulatory_vital_measurement','confirm_ambulatory_vital_measurement','confirm_ambulatory_vital_follow_up','confirm_ambulatory_vital_invalidation','web_read_vital_care_path_context','web_read_vital_care_path_page','web_commit_vital_care_path_packet','web_confirm_vital_care_path_packet','web_read_vital_care_review_page','web_commit_vital_care_review','web_confirm_vital_care_review') AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE'))) THEN RAISE EXCEPTION 'Vital package execute quarantine missing';END IF;
  IF has_table_privilege('authenticated','public.vital_care_paths','INSERT') OR has_table_privilege('service_role','care_private.vital_care_review_scopes','INSERT') THEN RAISE EXCEPTION 'Vital private/original table grants widened';END IF;
  fixture_count:=fixture_count+1;passed:=true;RAISE EXCEPTION USING ERRCODE='Z0001';
 EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;END;
 IF NOT passed OR fixture_count IS DISTINCT FROM 1 OR EXISTS(SELECT 1 FROM public.tenants WHERE id=t) OR EXISTS(SELECT 1 FROM auth.users WHERE id IN(u,reviewer)) OR EXISTS(SELECT 1 FROM public.vital_sign_catalog WHERE key='pulse') OR EXISTS(SELECT 1 FROM public.vital_sign_measurements WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_care_paths WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_care_review_events WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_private.vital_care_review_scopes WHERE tenant_id=t)
  OR EXISTS(SELECT 1 FROM public.roles WHERE id IN(r,review_role)) OR EXISTS(SELECT 1 FROM auth.sessions WHERE id IN(s,review_session)) OR EXISTS(SELECT 1 FROM public.clients WHERE id IN(c,other_client)) OR EXISTS(SELECT 1 FROM public.client_module_assignments WHERE tenant_id=t)
  OR EXISTS(SELECT 1 FROM public.client_vital_sign_settings WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_measurement_devices WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_device_calibrations WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_measurement_follow_ups WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_measurement_invalidations WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_sign_events WHERE tenant_id=t)
  OR EXISTS(SELECT 1 FROM public.employees WHERE id=fixture.employee_id) OR EXISTS(SELECT 1 FROM public.employee_employment_details AS employment WHERE employment.employee_id=fixture.employee_id) OR EXISTS(SELECT 1 FROM public.employee_documents WHERE id=qualification_doc) OR EXISTS(SELECT 1 FROM public.employee_qualifications WHERE id=qualification_id) OR EXISTS(SELECT 1 FROM care_private.vital_care_path_receipts WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_care_review_roots WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.vital_care_review_receipts WHERE tenant_id=t) THEN RAISE EXCEPTION 'Vital fixture or full rollback cleanup failed';END IF;
 PERFORM set_config('cp365.vital_workspace_test_evidence',jsonb_build_object('schemaVersion',1,'cleanupConfirmed',true,'expected',jsonb_build_object('tenantId',t,'clientId',c,'actorId',u,'measurementId',measurement,'measurementRequestId',measurement_request,'followUpId',follow_id,'followUpRequestId',follow_request,'invalidationId',invalidation_id,'invalidationRequestId',invalidation_request),'native',native_receipt,'nativePacket',native_packet,'followUpPacket',follow_packet,'followUpReceipt',follow_original,'invalidationPacket',invalidation_packet,'invalidationReceipt',invalidation_original,'legacyNative',legacy_original,'sources',source_original,'pathPacket',path_packet,'pathReceipt',path_receipt,'revisionPacket',revision_packet,'revisionReceipt',revision_receipt,'reviewPacket',review_packet,'reviewReceipt',review_receipt,'decisionPacket',decision_packet,'decisionReceipt',decision_receipt,'correctionPacket',correction_packet,'correctionReceipt',correction_receipt,'returnRequestPacket',return_request_packet,'returnRequestReceipt',return_request_receipt,'returnPacket',return_packet,'returnReceipt',return_receipt)::text,true);
END $test$;
SELECT current_setting('cp365.vital_workspace_test_evidence',true)::jsonb AS evidence;
ROLLBACK;
